import React from 'react';
import { motion } from 'motion/react';
import { fadeIn } from '../primitives/animations';

export type SystemMessageVariant = 'info' | 'warning' | 'error' | 'success';

export interface SystemMessageProps {
  /** Message content */
  content: string;
  /** Visual variant */
  variant?: SystemMessageVariant;
  /** Show icon */
  showIcon?: boolean;
  /** Additional CSS classes */
  className?: string;
  /** Animate entry */
  animate?: boolean;
  /** Dismissible */
  dismissible?: boolean;
  /** Called when dismissed */
  onDismiss?: () => void;
}

const variantStyles: Record<
  SystemMessageVariant,
  { bg: string; border: string; text: string; icon: string }
> = {
  info: {
    bg: 'bg-blue-50',
    border: 'border-blue-200',
    text: 'text-blue-800',
    icon: 'text-blue-500',
  },
  warning: {
    bg: 'bg-amber-50',
    border: 'border-amber-200',
    text: 'text-amber-800',
    icon: 'text-amber-500',
  },
  error: {
    bg: 'bg-red-50',
    border: 'border-red-200',
    text: 'text-red-800',
    icon: 'text-red-500',
  },
  success: {
    bg: 'bg-emerald-50',
    border: 'border-emerald-200',
    text: 'text-emerald-800',
    icon: 'text-emerald-500',
  },
};

const icons: Record<SystemMessageVariant, React.ReactNode> = {
  info: (
    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
      <path
        fillRule="evenodd"
        d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
        clipRule="evenodd"
      />
    </svg>
  ),
  warning: (
    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
      <path
        fillRule="evenodd"
        d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"
        clipRule="evenodd"
      />
    </svg>
  ),
  error: (
    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
      <path
        fillRule="evenodd"
        d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"
        clipRule="evenodd"
      />
    </svg>
  ),
  success: (
    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
      <path
        fillRule="evenodd"
        d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
        clipRule="evenodd"
      />
    </svg>
  ),
};

/**
 * System/info message
 *
 * Displays system notifications, warnings, or informational messages
 * in the chat flow. Centered and styled distinctly from user/AI messages.
 *
 * @example
 * ```tsx
 * <SystemMessage content="Session started" variant="info" />
 *
 * <SystemMessage
 *   content="Rate limit reached. Please wait."
 *   variant="warning"
 *   dismissible
 *   onDismiss={() => setShowWarning(false)}
 * />
 * ```
 */
export const SystemMessage: React.FC<SystemMessageProps> = ({
  content,
  variant = 'info',
  showIcon = true,
  className = '',
  animate = true,
  dismissible = false,
  onDismiss,
}) => {
  const styles = variantStyles[variant];

  const Wrapper = animate ? motion.div : 'div';
  const wrapperProps = animate
    ? { variants: fadeIn, initial: 'hidden', animate: 'visible' }
    : {};

  return (
    <Wrapper
      className={`flex justify-center ${className}`}
      {...wrapperProps}
    >
      <div
        className={`
          inline-flex items-center gap-2
          px-4 py-2 rounded-full
          text-sm font-medium
          border
          ${styles.bg} ${styles.border} ${styles.text}
        `}
      >
        {showIcon && <span className={styles.icon}>{icons[variant]}</span>}
        <span>{content}</span>
        {dismissible && (
          <button
            onClick={onDismiss}
            className={`
              ml-1 p-0.5 rounded-full
              hover:bg-black/5 transition-colors
              ${styles.icon}
            `}
            aria-label="Dismiss"
          >
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
              <path
                fillRule="evenodd"
                d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z"
                clipRule="evenodd"
              />
            </svg>
          </button>
        )}
      </div>
    </Wrapper>
  );
};

export default SystemMessage;
